import numpy as np

def test_issubdtype(scale, offset):
    try:
        val = scale + offset
        if hasattr(val, 'dtype'):
            res = np.issubdtype(val.dtype, np.floating)
        else:
            res = np.issubdtype(type(val), np.floating)
        print(f"Scale: {type(scale)}, Offset: {type(offset)} -> Floating: {res}")
    except Exception as e:
        print(f"Error: {e}")

test_issubdtype(np.array(1), np.array(0))
test_issubdtype(1, 0)
test_issubdtype(np.array(1.0), np.array(0.0))
test_issubdtype(1.0, 0.0)

